// GENERATED by scripts/generate-types.ts from schema/*.schema.json.
// Do not edit. Run `bun run generate` after a schema changes; CI runs
// `--check` and refuses a tree where this file is not what the schemas say.
//
// The schemas are frozen (`schema/frozen.json` holds a sha256 of each), so
// this file changing is always a deliberate act with a version behind it.

/**
 * Wringer acceptance evidence
 *
 * Generated from `schema/acceptance-v2.schema.json`. Do not edit.
 */
export type AcceptanceV2 = {
  /** Always `wringer.acceptance.v2` in this format. */
  "schema_version": "wringer.acceptance.v2";
  /** One key per state, always all five. These are counts over an ENUMERATED population — the criteria the approved spec declares — so a zero here is a real zero rather than the invented one the absence law forbids elsewhere. */
  "counts": {
    "evidenced": number;
    "unevidenced": number;
    "gate-failed": number;
    "gate-did-not-run": number;
    "human": number;
  };
  /** In the order the approved spec declares them. Nothing here is sorted by state: a ranking of criteria would be this artifact deciding which debts matter, which is the reader's call. */
  "criteria": {
    /** The criterion id, exactly as written in `wringer.spec.yaml`. The join key — never slugged or normalised, because a normalised join is a silent mis-bind. */
    "criterion": string;
    "title": string;
    /** From the spec. Only a required criterion can refuse delivery, and only when it is also bound. */
    "required": boolean;
    /** `evidenced` — bound, passed this run, and the record shows the gate can fail. `unevidenced` — unbound, or bound but born green. `gate-failed` — the gate ran and failed, so the criterion is not met: the ordinary honest state of work in progress. `gate-did-not-run` — bound, but no result in this bundle (skipped, interrupted); absence is absence, never a pass-through to an older green. `human` — answered by people, and nothing here scored it. */
    "state": "evidenced" | "unevidenced" | "gate-failed" | "gate-did-not-run" | "human";
    /** The gate whose `proves:` names this criterion, or null when nothing binds it. **In v2 null is not the same as uncovered**: a criterion may be covered by a witness instead, in which case this stays null and `witness` is present. Null with no witness is a DEBT, not an error. */
    "gate": string | null;
    /** The bound gate's command, after redaction. Null when unbound or human. Identity for the discrimination record is `(gate id, command)`: edit the command and the history resets, because editing is how checks narrow. */
    "command": string | null;
    /** Where the record shows this gate can fail. Null for every state except `evidenced`, and null WITH a reason rather than an empty object — a receipt that names nothing would be the claim this artifact exists to refuse. */
    "receipt": {
      /** `failure` — a recorded genuine failure of this exact pair (not a timeout, not exit 127). `sensitive` — a `--prove` pass recorded it failing on the pre-change tree while passing on the changed one. `witness` — a check WRINGER authored for this criterion, proved red for the right reason on the pre-change tree before any work began, pinned over its bytes, command and materialisation path, and passing on the changed tree. */
      "kind": "failure" | "sensitive" | "witness";
      /** Repo-relative path to the bundle holding the receipt, so a reader can go and look. */
      "bundle": string;
      /** PRESENT ONLY on a `sensitive` receipt: the line the sensitivity rests on, carried verbatim from `vacuity.json`. Load-bearing rather than decorative — a sensitivity receipt inherits vacuity's blind spot, so a gate whose own command arrived with the change reads sensitive for that reason alone, and this line is how a reader tells. Deliberately NOT classified here: SPEC_VACUITY §4b's law is to make the failure visible, never to auto-classify it. */
      "cites"?: string;
    } | null;
    /** Why this state, in words a person can act on — including the one-run remedy when a gate is born green. */
    "reason": string;
    /** Whether this row stops delivery. **The v1-to-v2 change lives here**: in v1 only a required and BOUND criterion could refuse, so `gate: null` implied `refuses: false`. In v2 a required criterion covered by a witness refuses on the same terms, with `gate` null and `witness` present. A v1 reader meeting that row would draw the wrong conclusion, which is why the version moved rather than a key being added. */
    "refuses": boolean;
    /** Wringer's own manufactured evidence for this criterion, or null when the run had none. Present independently of `receipt`: a witness that was DISCARDED, or that failed on the changed tree, is recorded here and earns no receipt — which is the case a reader most needs to be able to see, because it is the one where a green gate and an unsatisfied criterion coexist. **This says nothing about agreement with an intended fix**: a witness proves the stated criterion could fail and was made to pass, and where the criterion under-describes the intent the witness inherits that gap. */
    "witness": {
      /** The digest pinned before the first worker turn, covering the witness bytes. Re-read from disk and compared immediately before every execution; a mismatch VOIDs the run rather than failing a gate. */
      "pinned_sha256": string;
      /** How the witness failed on the PRE-CHANGE tree, from the runner's own structure rather than from reading its message. `assertion` is the only proved red: the runner collected the check and the check then failed. `collection_error` covers an import failure, a syntax error, nothing collected, and a failure that could not find what it was written against — none of which says anything about the criterion, because such a check turns green the moment any file or binary of that name exists. `green` means it demonstrated nothing and was discarded. */
      "proved_red": "assertion" | "collection_error" | "green";
      /** What the same pinned bytes did on the CHANGED tree. `not_run` when the witness was discarded before it could be consulted. */
      "result": "passed" | "failed" | "not_run";
      /** Why this witness may evidence nothing, or null. A discarded witness leaves its criterion UNCOVERED and routes to a human, which is an honest outcome and deliberately not a failure. */
      "discarded"?: string | null;
    } | null;
  }[];
  /** What this artifact does NOT say, travelling with the numbers rather than living in a spec nobody opened. Four entries at minimum, each pinned by content — including that a sensitivity receipt says the gate's result differed between two trees, not that the difference was the change. */
  "limits": string[];
};

