/**
 * Wringer bench manifest
 *
 * Generated from `schema/bench-manifest-v2.schema.json`. Do not edit.
 */
export type BenchManifestV2 = {
  "schema_version": "wringer.bench.v2";
  /** Also names the worktrees — `<bench_id>-<contender_id>`, never the bare contender id, because a colliding worktree path is force-removed and contender ids are stable across benches. */
  "bench_id": string;
  /** Local ISO-8601 with offset, seconds precision. */
  "started_at": string;
  /** The job. A bench of repair needs something to repair, so a green baseline is refused before any of this is written. */
  "baseline": {
    /** The detached sha every contender worktree was checked against. One tree, checked rather than assumed. */
    "sha": string;
    /** The baseline's verify bundle, by path, inside the kept baseline worktree. */
    "run_dir": string;
    /** The required gates that failed at the baseline: the work every row was measured on. */
    "failing_gates": string[];
  };
  /** The SAME ceiling every contender's loop was handed. Enforcement is the loop's own, which stops after finishing the step in flight, so a contender's true ceiling is this plus at most one worker turn plus one verify — the loop's documented behaviour, not bench's to re-legislate. */
  "contender_wall_clock": number;
  /** One row per contender ATTEMPT, in DECLARED order — never outcome order. A test pins that a later contender which converged faster does not float up. With `attempts: 1` this is one row per contender, exactly as v1 published. */
  "contenders": {
    "contender": string;
    /** A loop reason, or `error`. Not a grade. */
    "outcome": string;
    "reason": string;
    "iterations": number;
    "wall_clock_ms": number;
    "loop_ref": string;
    "head_moved": boolean;
    "final_run"?: string;
    "agent"?: string;
    /** PRESENT ONLY when the agent reported it. Absent means unreported, never zero. */
    "usage"?: {
      "used": number;
      "size": number;
      "sessions": number;
      "cost"?: {
        "amount": number;
        "currency": string;
      };
    };
    /** Which independent attempt this row is, 1-based. PRESENT EXACTLY WHEN the bench made more than one attempt each — a number that is always 1 is noise in the artifact a stranger reads, and its absence is what keeps a single-attempt bench's rows identical to the ones v1 published. Rows are still in DECLARED order: contender by contender, attempt by attempt, never outcome order, and never sorted by anything. */
    "attempt"?: number;
  }[];
  /** What this artifact does NOT say, travelling with the numbers rather than living in a spec nobody opened — a benchmark is the artifact most likely to be read as a larger claim than it is. At minimum three entries, and a test pins each by CONTENT: one run per contender; usage is the agent's own unverified report; and a green gate proves the gates went green, not that the fix is honest. */
  "limits": string[];
  /** How many independent attempts each contender made. PRESENT ONLY when more than one — absent means one each, which is what every bench did before this key existed. Each attempt gets its own worktree, its own loop bundle and its own ledger, all detached from one checked baseline commit under one shared ceiling. What repeats buy is NOT a ranking: it is whether a contender agrees with ITSELF, which is the agent's own nondeterminism made visible — the same finding a flaky gate is one level down. Across contenders there is still no comparison and no field here that orders one (ruling 6). */
  "attempts"?: number;
  /** How many attempts ran at once. PRESENT ONLY when more than one. When present, `wall_clock_ms` on every row is CONTENDED and rows may not be compared on it — it records elapsed time under load, which is not the quantity a serial bench records. The ledger's events are also in declared order rather than completion order, because it is written by one thread: the `prev_hash` chain is what that protects, and two threads appending to it would break the bundle's own tamper-evidence silently. */
  "parallel"?: number;
};

