/**
 * Wringer certificate
 *
 * Generated from `schema/certificate-v1.schema.json`. Do not edit.
 */
export type CertificateV1 = {
  /** Always `wringer.certificate.v1` in this format. */
  "schema_version": "wringer.certificate.v1";
  /** ISO-8601, when `wring deliver` wrote this. The machine's clock, recorded and not checked. */
  "written_at": string;
  /** What is being handed over. Enough for a reader to know which change this is about, and no more: there is no author, no committer and no agent name anywhere in this record, because the offline check must not be able to read one. A verification whose answer moves when the author changes is a verification of the author. */
  "change": {
    /** The approved spec's title, or the task, or the run. Never invented — it is taken from something a person wrote. */
    "title": string;
    "branch": string;
    "base": string;
    /** The commit the gates were verified against, or null when the tree could not be read. Checked by `wring audit` against the clone in front of the reader. */
    "commit": string | null;
    "files_changed": number;
  };
  /** The run whose record this document renders. */
  "run": {
    "id": string;
    /** Repo-relative, like every other cross-bundle reference in this program — never absolute, because an artifact whose whole purpose is that a stranger can read it must not carry somebody's home directory. */
    "bundle": string;
  };
  /** The document the work was authorised by. `sha256` is over `wringer.spec.yaml`'s bytes, and `wring audit` re-hashes the clone's copy: a mismatch says the spec moved after the run, which is a fact the reader needs and is not by itself a forgery. */
  "spec": {
    "sha256": string | null;
  };
  /** Which acceptance version this was rendered from, and its counts verbatim. The counts are carried rather than recomputed so that `wring audit` can check the summary against the rows — the cheapest forgery is an edited number over honest rows. */
  "acceptance": {
    "schema_version": string | null;
    "counts": Record<string, unknown>;
  };
  /** Every requirement the approved spec declares, in the order it declares them. **Sorted by nothing.** Ranking these would be this document deciding which debts matter, which is the reader's call — the same refusal `acceptance.json` makes, for the same reason. */
  "requirements": {
    /** The criterion id from `wringer.spec.yaml`, never slugged or normalised: it is the join key `wring audit` uses against the clone's spec, and a normalised join is a silent mis-bind. */
    "id": string;
    "title": string;
    "required": boolean;
    /** The acceptance record's own state word, carried unchanged. It is here for the machine; nothing renders it to a reader. */
    "state": string;
    /** The plain-English label a reader sees, IN the record. The reviewer's first gap was that `unevidenced` is not a word they use — so the words a person reads travel with the row rather than being re-derived by every surface that renders it. A `(state, cause)` pair the renderer has no wording for produces an explicit refusal to translate, never the nearest phrase. */
    "says": string;
    /** The same fact as a sentence: what this state means for the person deciding whether to merge. */
    "means": string;
    /** The gate whose `proves:` names this requirement, or null when nothing binds it. Null is a DEBT, not an error. */
    "check": string | null;
    "command": string | null;
    /** Where the record shows this check failing, copied from the acceptance row, or null. This is what `wring audit` re-checks per receipt — and where the run it names did not travel with the document, the audit says so in those words rather than counting it either way. */
    "receipt": Record<string, unknown> | null;
    /** The engine's own prose for this state, carried verbatim. It holds the remedy, and this document does not regenerate it from the label above. */
    "reason": string;
    "refuses": boolean;
    /** A person's answer to a requirement only a person can settle, copied from the acceptance row, or null. It carries the verdict, the name, the date and — the reason this key is here at all — the NOTE. A note reading `your words here5` reached a delivered branch as the stated reason a requirement passed, and was caught only by somebody opening the YAML, because no surface in the program showed a judgement note to anybody. */
    "judgement": Record<string, unknown> | null;
  }[];
  /** What this document does NOT say. The acceptance record's list, plus this document's own — never fewer. */
  "limits": string[];
};

