/**
 * Wringer coverage
 *
 * Generated from `schema/coverage-v1.schema.json`. Do not edit.
 */
export type CoverageV1 = {
  /** Always `wringer.coverage.v1` in this format. */
  "schema_version": "wringer.coverage.v1";
  /** The two numbers, over an ENUMERATED population — the requirements an approved spec declares — so a zero here is a real zero rather than the invented one the absence law forbids elsewhere. They are carried rather than left to be recomputed so that a reader can check the summary against the rows, which is the cheapest forgery there is. */
  "counts": {
    /** How many requirements that a check COULD prove have one bound to them — a gate whose `proves:` names them, or a witness that covers them. */
    "covered": number;
    /** How many requirements a check could prove at all: every one not marked `human`. */
    "checkable": number;
    /** How many requirements needing a person have a `show:` command declared for them — something that will put the thing being judged in front of the person judging it. */
    "shown": number;
    /** How many requirements are marked `human`. */
    "needing_a_person": number;
  };
  /** In the order the approved spec declares them, and sorted by nothing: ranking these would be this artifact deciding which debts matter, which is the reader's call — the same refusal `acceptance.json` makes. */
  "requirements": {
    /** The criterion id exactly as `wringer.spec.yaml` writes it — the join key, never slugged. */
    "criterion": string;
    "title": string;
    /** Whether the spec marks this `human`. It decides which of the two questions below is asked at all. */
    "needs_a_person": boolean;
    /** Whether anything is bound that could prove this — **null on a row marked `human`, and null is not false.** False is a debt somebody could pay by writing a check; null is a question nobody asked, because no check can settle this requirement and none ever will. Collapsing those two is how a record comes to lie, which is the same reason `demonstrated_able_to_fail` is three-valued in `wringer.acceptance.v3`. */
    "covered": boolean | null;
    /** The gate bound to this requirement, or null. Null with `covered: true` means a witness covers it instead. */
    "check": string | null;
    /** Whether a `show:` command is declared for this requirement — **null on every row NOT marked `human`**, for the mirror of the reason above: nobody is going to be asked to judge it, so there is nothing to show them and no debt to record. */
    "shown": boolean | null;
    /** The declared command, after redaction, or null. Recorded because a reviewer deciding whether a judgement was informed needs to know what the person was shown — and because a command is a thing that RUNS, it is scrubbed on the way in like every other command this program records. */
    "show": string | null;
  }[];
  /** What this artifact does NOT say, travelling with the numbers rather than living in a spec nobody opened, and rendered on every surface that carries the number. One sentence, and it is the honest reading of what was counted: a BINDING, which is a declaration somebody made, and not a measurement of how much of the requirement that check actually exercises. */
  "limits": string[];
};

/**
 * Wringer decisions v2 — the plain-language companion to a spec
 *
 * Generated from `schema/decisions-v2.schema.json`. Do not edit.
 */
export type DecisionsV2 = {
  "schema_version": "wringer.decisions.v2";
  /** Decisions the drafter took INSTEAD of asking. Measured 2026-08-19: told to prefer visible assumptions and given no field to put one in, a drafter writes them into a criterion's test `guidance`, where the person approving the plan never reads them as decisions — 14 criteria across four replies to one unchanged PRD. This is the field that was missing. Approving the plan approves these. */
  "assumptions"?: {
    /** A slug, obeying the frozen open-question id rule BYTE FOR BYTE: `wringer-board revise` promotes an assumption into `open_questions`, so an id this file accepted and the spec loader would not is a spec the engine then refuses, leaving a person a broken file and an error about a document they never hand-edited. */
    "id": string;
    /** One plain sentence: what was decided. */
    "decision": string;
    /** One plain sentence: why it was decided that way. */
    "why": string;
    /** The question the person would otherwise have been asked. REQUIRED, and it is what stops this channel becoming a tidier place to hide a decision than `guidance` was: carrying the displaced question means the person is always one action away from asking it after all. */
    "instead_of_asking": string;
    /** The ids of criteria whose WORDING this assumption shaped — written by the drafter, which is the only party that knows: it made the decision and then wrote the criteria in the same reply. When the person overrules the assumption, every criterion named here is rendered STALE (worded before the correction) and `wring plan` REFUSES while one stands unreviewed. OPTIONAL, and its absence is not evidence of absence: an older sidecar has none, and a drafter may simply not emit them. The fallback is a heuristic note that is explicitly a LOWER BOUND, on the buried-decision detector's precedent. WRINGER NEVER RE-WORDS A CRITERION ITSELF — re-wording is the person's act. This channel makes the contradiction visible and refuses to proceed past it; it does not resolve it. */
    "criteria"?: string[];
  }[];
  /** One plain-language sentence per task: what the person will be able to DO when that task is done, beside the machine `objective` the engineer works from. NO WRITER AT PUBLICATION — the producer arrives with the plan's two registers. */
  "outcomes"?: {
    /** The id of a task in `wringer.spec.yaml`. A row naming a task the spec does not have is refused whole — content pointing at nothing, the same rule the gate sidecar applies to a `proves` naming no criterion. */
    "task": string;
    "outcome": string;
  }[];
  /** What the approver approved, recorded at the moment they approved it, so that a spec edited afterwards can be told from one that was not. NO WRITER AT PUBLICATION: the check was ruled OWED after review, because it would need one implementation in the engine and another in the board — two packages with no shared code and no dependency edge — over a canonical form that any normalisation difference would turn into `wring plan` accusing an honest person of editing their spec after approving it. The shape is reserved; the behaviour is not built. Absence of this block is NOT evidence of tampering and never becomes so: a spec approved by hand never claimed a fingerprint. */
  "consent"?: {
    /** Digest over the canonical serialisation of every question id with its answer and every assumption id with its decision. Prefixed with its algorithm, so a later one can arrive without a version spend. */
    "fingerprint": string;
    "approved_at"?: string;
    "questions"?: number;
    "assumptions"?: number;
  };
};

