  /** Which shape the failure wore. A CLOSED enum, because a face with no name is a face no reader can route on, and `diagnose.FACES` is the single definition it is derived from. `command_not_found`: the shell could not find the command at all (exit 127, or the text). `missing_module`: an interpreter started and could not import something (`No module named`). `not_executable`: the file was found and could not be run (exit 126, or `Permission denied`). */
  "face": "command_not_found" | "missing_module" | "not_executable";
