/**
 * Wringer execution record, v2 — the worker's containment
 *
 * Generated from `schema/execution-v2.schema.json`. Do not edit.
 */
export type ExecutionV2 = {
  "schema_version": "wringer.execution.v2";
  /** Which backend ran the GATES. Independent of the worker's containment in both directions: a repository may contain its worker and run its gates locally, or the reverse, or both, or neither. */
  "backend": "local" | "container";
  /** What that gate backend is WORTH. **`trusted_local` appears here legitimately in a v2 record** whenever the gates ran on this machine, and that is not in tension with a contained worker — it is SPEC_CONTAIN_V0 ruling 7, the same separation v1 already makes. Any guard reading this FILE for the string `trusted_local` is reading the wrong thing; the field to read is `worker_execution.declared.mode`. */
  "execution_mode": "trusted_local" | "container";
  /** The gate ids this run attempted, in declared order. */
  "gates": string[];
  /** Where `run.worker` runs, in two blocks that answer two different questions. Never folded into `execution_mode` — a single field covering both would be the one field in this file capable of lying, and it would lie in the direction of claiming more. */
  "worker_execution": {
    /** Repository POLICY, always present. This is `worker_execution`'s shipped meaning carried forward — *a statement about the repository's policy rather than about this invocation* — so it reads the same on the verify lap before a worker and the one after. It is worth reading because a repository that cannot honour its declaration produces no bundle at all: the declaration is checked before any bundle is opened and refuses with a named reason, never degrading to `trusted_local`. */
    "declared": {
      /** **`contained`**, and deliberately not `sandboxed`, `isolated` or `secure` — the rule the `execution_mode` enum already follows. Also deliberately not `container`, which is the GATE vocabulary: two words one letter apart with different meanings is a trap for a bundle reader, so the constants are named apart (`containment.WORKER_CONTAINED` beside `backend.CONTAINED`). */
      "mode": "contained";
      /** The runtime id as declared. Apple's `container` cannot appear — `config.parse` refuses it, because its flags have not been verified against the argv Wringer builds. */
      "runtime": "docker" | "podman" | "nerdctl";
      /** The image as the repository declared it. There is no default and there will not be one: Wringer ships no coding agent from any vendor — the published image's own Dockerfile says so and gives the reason — so the image that runs a worker is one a human named and one that carries the agent they chose. */
      "image": string;
      /** The environment-variable NAMES the worker was allowed to see. Everything not named is withheld, so the worker gets a stated environment rather than the operator's whole shell. The argv uses `--env NAME` and never `--env NAME=VALUE`: a value in an argv is readable by anyone who can run `ps`, and that difference is the whole of what "Wringer stores no credential" means at the point of spawn. */
      "env_allowlist": string[];
      /** `uid` or `uid:gid` if the repository declared one, else null for the image's own user. Offered rather than applied — but read `limits`: a worker's whole job is to WRITE the mount, so an image running as root leaves root-owned files in the developer's real repository. That consequence differs in kind from the gate case the same ruling was written for. */
      "user": string | null;
      /** What the worker was permitted to reach. A closed vocabulary with no way to spell "unrestricted": a worker that wants the open network declares no containment at all, and gets a v1 record saying `trusted_local` out loud. */
      "egress": {
        /** `none` is `--network none`, which the runtime enforces. `allowlist` is a netns holder: a separate container owning the network namespace with `NET_ADMIN`, arming an address allowlist that the worker — joining that namespace WITHOUT `NET_ADMIN` — is subject to and cannot disarm. The boundary is deliberately not inside the thing it bounds. */
        "policy": "none" | "allowlist";
        /** Allowlist only. The hostnames the repository declared. **What is enforced is the addresses these resolved to, not the names** — see `established.egress.resolved` and the co-tenancy row in `limits`. */
        "hosts"?: string[];
        /** Allowlist only. The TCP ports admitted to each resolved address. Defaults to `[443]`, and exists as a key because a self-hosted or proxied model endpoint on another port would otherwise fail closed with no named reason. */
        "ports"?: number[];
        /** Allowlist only. The image the netns holder runs, which must carry `iptables` — checked before any worker starts, because a policy that cannot be established must refuse rather than quietly become no policy. No default here either. */
        "broker_image"?: string | null;
      };
    };
    /** What THIS lap actually stood up. **Absent when it stood up nothing, and absence is the honest reading rather than a gap.** `wring verify`, `wring start` and a loop's own verify laps all write this record without starting a container, so a placeholder here would be the record claiming a containment that did not happen — which is the single failure SPEC_CONTAIN_V0 is answerable to. */
    "established"?: {
      /** The RESOLVED path of the runtime binary, because two machines with `runtime: docker` can be running very different things. No version and no image digest: reading either means spawning a process, and nothing in a verification should spawn a process to decorate a record. */
      "runtime_path": string | null;
      /** Where the repository was mounted inside the worker container — always `/workspace`, matching the published Dockerfile's WORKDIR and its `safe.directory` scoping. **Read-write by design**, because changing the tree is the worker's entire job, which is also the honest limit of this boundary. */
      "mount": string;
      /** Present only for an armed allowlist. */
      "egress"?: {
        /** **The exact addresses the allowlist admitted.** Not decoration: a reader who wants to know what the worker could reach reads this array rather than trusting a hostname, and it is what makes a rotation failure legible after the fact. Resolution happens inside the broker container rather than on the Wringer host, because on macOS the runtime's containers live in a Linux VM with its own resolver and a host-side answer can name an address the container's resolver never returns — which would block the very endpoint the allowlist was written to admit. */
        "resolved": string[];
      };
    };
  };
  /** Gate container backend only, unchanged from v1. */
  "runtime"?: "docker" | "podman" | "nerdctl";
  /** Gate container backend only, unchanged from v1. */
  "runtime_path"?: string | null;
  /** Gate container backend only, unchanged from v1. */
  "image"?: string;
  /** Gate container backend only, unchanged from v1. */
  "mount"?: string;
  /** Gate container backend only, unchanged from v1. */
  "network"?: boolean;
  /** Gate container backend only, unchanged from v1. */
  "env_allowlist"?: string[];
  /** Gate container backend only, unchanged from v1. */
  "user"?: string | null;
  /** What this record does NOT claim, travelling with it rather than living in a spec nobody opened. **Not v1's list**, and the difference is the point: v1's fourth row says `run.worker` is not contained and `worker_execution` always says `trusted_local`, which inside this record would be a denial of its own claim — a green artifact carrying somebody else's caveat, in the one field this repository invented so a record could state what it does not claim. Pinned by CONTENT in the tests, not by non-emptiness. */
  "limits": string[];
};

/**
 * Wringer execution record
 *
 * Generated from `schema/execution.schema.json`. Do not edit.
 */
export type Execution = {
  "schema_version": "wringer.execution.v1";
  /** Which backend ran the gates. `local` is what every run did before this record existed and is what a config with no `execution:` section still does. */
  "backend": "local" | "container";
  /** What that backend is WORTH, which is a different question from where it is. `trusted_local` means the gate ran on this machine with the invoking user's privileges and the whole environment inherited — **never `sandboxed`, never `isolated`**, because `.wringer.yaml` is arbitrary code by design and it ran as you. `container` means the command was handed to a container runtime with a named image and the argv recorded beside it, which is what the word means here and no more. */
  "execution_mode": "trusted_local" | "container";
  /** The gate ids this run attempted, in declared order. Present so a reader can tell a scoped run from a full one without joining to the manifest. */
  "gates": string[];
  /** Where `run.worker` runs, recorded SEPARATELY and never folded into `execution_mode` — a single field covering both would be the one field in this file capable of lying, and it would lie in the direction of claiming more. It is `trusted_local` whenever the repo declares a worker, because the container backend contains GATES and not the worker: the published image deliberately ships no coding agent, so an agent worker cannot run inside it (the Dockerfile's own comment says so), and pretending otherwise would break every real loop. `null` when the repo declares no `run:` section at all. This is a statement about the repository's policy rather than about this invocation, so it reads the same on the verify lap before a worker and the one after it. */
  "worker_execution": "trusted_local" | null;
  /** Container backend only. The runtime id as declared: `docker`, `podman` or `nerdctl`. Apple's `container` cannot appear, because `config.parse` refuses it — its flags have not been verified against the argv Wringer builds, and a silently-ignored `--network none` would record `network: false` over a live network (SPEC_EXEC_V0 ruling 4). */
  "runtime"?: "docker" | "podman" | "nerdctl";
  /** Container backend only. The RESOLVED path of the runtime binary, because two machines with `runtime: docker` can be running very different things and a bundle that says only "docker" cannot tell them apart. No version: reading one means spawning a process, and nothing in a verification should spawn a process to decorate a record. */
  "runtime_path"?: string | null;
  /** Container backend only. The image as the repository declared it. There is no default and there will not be one — Wringer runs the image you wrote down, never one it guessed, the same rule `judge.endpoint` follows. A moving tag Wringer chose would put "ran in a container" in the evidence with nobody having decided which container. */
  "image"?: string;
  /** Container backend only. Where the repository was mounted — always `/workspace`, matching the published Dockerfile's WORKDIR and its `safe.directory` scoping. **Read-write by design and not by oversight:** the evidence bundle is written to `.wringer/` inside the tree, so a read-only mount fails late and confusingly. It is also the honest limit of this boundary — a hostile gate can still corrupt the tree you handed it. */
  "mount"?: string;
  /** Container backend only. Whether the container had a network. **Off by default**, via `--network none` in the argv; `true` means the repository typed `network: true`, which is the only kind of opt-in that means anything. Recorded either way, so a reader never has to infer it from a default. */
  "network"?: boolean;
  /** Container backend only. The environment-variable NAMES the container was allowed to see. Everything not named is withheld, so a container gets a stated environment rather than the operator's whole shell — which is what keeps host SSH, cloud and forge credentials out of it by construction rather than by filtering. The argv uses `--env NAME` and never `--env NAME=VALUE`: a value in an argv is readable by anyone who can run `ps`. */
  "env_allowlist"?: string[];
  /** Container backend only. `uid` or `uid:gid` if the repository declared one, else null for the image's own user (uid 1000 in the published image). Offered rather than applied: overriding an image's declared user silently would contradict an image this repo does not own at run time, and a Linux bind mount owned by another uid is the case that needs it. Digits and one optional colon only — it reaches the runtime as a positional argument, so anything else could be read as a flag. */
  "user"?: string | null;
  /** What this record does NOT claim, travelling with it rather than living in a spec nobody opened — the pattern `wringer.health.v1` and `wringer.acceptance.v1` set. An execution record is exactly the artifact a reader inflates into a security claim, and the container row is the one that would be inflated furthest. Pinned by CONTENT in the tests, not by non-emptiness. */
  "limits": string[];
};

