/**
 * Wringer falsification
 *
 * Generated from `schema/falsification-v1.schema.json`. Do not edit.
 */
export type FalsificationV1 = {
  /** Always `wringer.falsification.v1` in this format. */
  "schema_version": "wringer.falsification.v1";
  /** `measured` — mutants were made and the bound checks ran against each. `inconclusive` — the measurement could not be made honestly, and NOTHING is claimed either way. `not-applicable` — there was nothing to attempt. **The three are never collapsed**: an unmeasurable run must not score zero and must not score full marks, which is the trap the control run exists to catch. A scratch copy carries tracked files only, so in a repository whose dependencies are not committed every gate fails there and every mutant would be recorded as CAUGHT — a perfect score produced by a broken environment, which is worse than no measurement. */
  "verdict": "measured" | "inconclusive" | "not-applicable";
  /** Why, in the engine's own words, for the two verdicts that are not a measurement. Empty on `measured`. */
  "reason": string;
  /** Over an ENUMERATED population — the mutants this run actually attempted — so a zero is a real zero. `attempted` is what was tried, NOT what was possible: see `truncated`. */
  "counts": {
    "attempted": number;
    "caught": number;
    "survived": number;
  };
  /** The BOUND checks that ran against each mutant — the ones whose `proves:` names a requirement. A gate binding nothing has no opinion about whether a mutant broke anything anybody asked for. Empty on a verdict that is not a measurement. */
  "gates": string[];
  /** Every mutant, in the order it was attempted. **Deterministic**: the file order is sorted, each file's mutations keep their diff order, and the ceiling is spread round-robin across files — so two runs of one commit attempt the same mutations in the same order, and a survivor is a fact somebody can go and reproduce. */
  "attempts": {
    /** Repo-relative. **Load-bearing rather than decorative**: a mutation in a file the bound checks never execute — a test file, a fixture — survives because nothing ran it, which says only that, and the path is how a reader tells that case from a mutation of code the checks were supposed to be watching. */
    "path": string;
    "line": number;
    /** The line as delivered, verbatim. Carried so a reader can see what was broken without opening the tree, and checked against the file before the mutation is applied — a diff's line numbers are about the diff's idea of the file, and mutating by number alone would break a line nobody chose. */
    "was": string;
    "became": string;
    /** The substitution, as `'what' -> 'what it became'`. Textual, and nothing here parses the code — that buys language independence and costs precision, which `limits` states out loud. */
    "mutation": string;
    /** The bound checks that FAILED on this mutant. Empty when it survived. */
    "caught_by": string[];
    /** Whether every bound check still passed. True is the finding; false is the ordinary case and is not a claim that the check is good. */
    "survived": boolean;
  }[];
  /** PRESENT ONLY when a ceiling was actually reached, and it says how many mutations were possible and not attempted. A key saying 'nothing was truncated' on every clean run is the caveat-over-a-clean-record shape this project refuses — and a silent truncation reads as 'we tried everything', which is the worse of the two mistakes. */
  "truncated"?: string;
  "duration_ms": number;
  /** What this measurement does NOT say, travelling with the numbers rather than living in a spec nobody opened, and rendered on every surface that carries them. */
  "limits": string[];
};

