export type HealthReport = {
  "schema_version": "wringer.health.v1";
  /** The coverage statement, and it LEADS the report. A health tool that silently skips unreadable history is the narrowing defect with a lens in its hand — so there is no quiet path: a bundle is read, or it is named here. `discovered == read + skipped + duplicates` and a test pins that, rather than merely pinning that the skip count matches the skip list, which a bundle dropped before classification passes silently. */
  "coverage": {
    /** The search roots that were walked, named so a reader can check the scope. Discovery is over named roots rather than 'everything reachable', because a scope nobody can state is the defect this command hunts. */
    "roots": string[];
    "read": number;
    "counts": {
      "run": number;
      "loop": number;
      /** Read and shown, and they decide NOTHING. `wring bench` refuses to start unless the baseline is red, so every bench guarantees a failed row for every required gate on a tree nobody changed, under the same identity as the repo's real gates. */
      "bench": number;
    };
    /** Every bundle that was seen and could not be read, WITH ITS REASON. A directory holding a `manifest.json` is discovered whether or not the manifest parses: seeing and classifying are separate steps, and only the second may fail. */
    "skipped": {
      "receipt": string;
      "reason": string;
    }[];
    /** The same bundle reached by two roots — `--from` naming a path already searched, or a CI restore of the repo's own runs. Counted ONCE and named, because counting twice moves gates across the history floor and pads the window until an older failure falls out of it. */
    "duplicates": {
      "receipt": string;
      "already_read_as": string;
    }[];
    "discovered": number;
  };
  /** One entry per `(id, command)` pair that is still the contract. History attaches to the PAIR: change the command and the record starts over, because the old evidence is about a different check and editing is how checks most often narrow. */
  "gates": unknown[];
  /** Pairs that are no longer the contract — a prior definition of an edited gate, or a gate the config no longer declares. History and receipts are shown and NO verdict is claimed. Without this the window, which is scoped to a pair's own runs, freezes for a deleted gate and it reads `alive` in perpetuity from evidence of arbitrary age. */
  "retired": unknown[];
  /** What this report does not say, travelling with it rather than living in a spec nobody opened. At minimum four entries, each pinned by CONTENT: the claim is about the record and not the gate; only declared gates are visible; thin history cannot support `zombie` though it can support `alive`; and a sensitive row proves the gate's result changed with the tree, NOT that the change was honest — an agent deleting an already-failing assertion records one for the wrong reason, and this instrument inherits that blind spot whole. */
  "limits": string[];
};

