  "refusals": number;
  /** The agent's own last account of itself, if it gave one, carried verbatim BESIDE the description rather than parsed into it. Detection never reads this — F6's law: route on facts, hint on text, claim on neither — and the deprecated adapter's empty success is precisely why text cannot be trusted here. */
  "engine_words"?: string;
